import java.io.File;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.Random;

/** Differential test for MaxiCode DecodedBitStreamParser.decode(byte[], int): original vs refactored. */
public final class McDiff {

  static URLClassLoader loader(String dir) throws Exception {
    return new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
  }

  static Method decodeMethod(ClassLoader cl) throws Exception {
    Class<?> c = Class.forName("com.google.zxing.maxicode.decoder.DecodedBitStreamParser", true, cl);
    Method m = c.getDeclaredMethod("decode", byte[].class, int.class);
    m.setAccessible(true);
    return m;
  }

  static String run(Method decode, byte[] bytes, int mode) {
    try {
      Object dr = decode.invoke(null, bytes, mode);
      String text = (String) dr.getClass().getMethod("getText").invoke(dr);
      return "OK|" + text;
    } catch (Throwable t) {
      Throwable c = (t.getCause() != null) ? t.getCause() : t;
      return "EX|" + c.getClass().getName();
    }
  }

  public static void main(String[] args) throws Exception {
    Method oldD = decodeMethod(loader(args[0]));
    Method newD = decodeMethod(loader(args[1]));
    Random r = new Random(77);

    long total = 0;
    long ok = 0;
    long mism = 0;
    int[] modes = { 2, 3, 4, 5, 6 };

    for (int trial = 0; trial < 400000; trial++) {
      // MaxiCode codewords are 6-bit (0..63); full set is 144 symbols.
      byte[] bytes = new byte[144];
      for (int i = 0; i < bytes.length; i++) {
        bytes[i] = (byte) r.nextInt(64);
      }
      int mode = modes[r.nextInt(modes.length)];
      String a = run(oldD, bytes, mode);
      String b = run(newD, bytes, mode);
      total++;
      if (a.startsWith("OK")) {
        ok++;
      }
      if (!a.equals(b)) {
        mism++;
        if (mism <= 20) {
          System.out.println("MISMATCH mode=" + mode);
          System.out.println("  old: " + a);
          System.out.println("  new: " + b);
        }
      }
    }
    System.out.println("----");
    System.out.println("Total decodes:    " + total);
    System.out.println("Successful (OK):   " + ok);
    System.out.println("Mismatches:       " + mism);
    System.out.println(mism == 0 ? "RESULT: IDENTICAL BEHAVIOR" : "RESULT: DIFFERENCES FOUND");
  }
}

